def open_lock(deadends, target):
    dead = set(deadends)
    if '0000' in dead:
        return -1

    def neighbors(state):
        result = []
        for i in range(4):
            digit = int(state[i])
            for delta in (1, -1):
                new_digit = (digit + delta) % 10                          # wrap around: 9+1=0, 0-1=9
                result.append(state[:i] + str(new_digit) + state[i + 1:])
        return result

    # a naive (but still correct) BFS, exploring level by level, using a LIST as the frontier
    visited = {'0000'}
    frontier = ['0000']
    steps = 0
    while frontier:
        if target in frontier:
            return steps
        next_frontier = []
        for state in frontier:
            for nxt in neighbors(state):
                if nxt not in dead and nxt not in visited:
                    visited.add(nxt)
                    next_frontier.append(nxt)
        frontier = next_frontier                                           # rebuilding a new list every level: works, but not using a true queue
        steps += 1
    return -1


if __name__ == "__main__":
    print(open_lock(["8888"], "0009"))

