import java.util.*;

public class Main {
    int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;

        Set<String> visited = new HashSet<>();
        visited.add("0000");
        List<String> frontier = new ArrayList<>();                                  // a naive (but still correct) BFS using a LIST as the frontier
        frontier.add("0000");
        int steps = 0;
        while (!frontier.isEmpty()) {
            if (frontier.contains(target)) return steps;
            List<String> nextFrontier = new ArrayList<>();
            for (String state : frontier) {
                for (String next : neighbors(state)) {
                    if (!dead.contains(next) && !visited.contains(next)) {
                        visited.add(next);
                        nextFrontier.add(next);
                    }
                }
            }
            frontier = nextFrontier;                                                  // rebuilding a new list every level: works, but not using a true queue
            steps++;
        }
        return -1;
    }

    List<String> neighbors(String state) {
        List<String> result = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            int digit = state.charAt(i) - '0';
            for (int delta : new int[]{1, -1}) {
                int newDigit = ((digit + delta) % 10 + 10) % 10;                            // wrap around: 9+1=0, 0-1=9
                result.add(state.substring(0, i) + newDigit + state.substring(i + 1));
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] deadends = {"8888"};
        System.out.println(solution.openLock(deadends, "0009"));
    }
}

