from collections import deque

def open_lock(deadends, target):
    dead = set(deadends)
    if '0000' in dead:
        return -1
    if target == '0000':
        return 0

    def neighbors(state):
        for i in range(4):
            digit = int(state[i])
            for delta in (1, -1):
                new_digit = (digit + delta) % 10
                yield state[:i] + str(new_digit) + state[i + 1:]

    visited = {'0000'}
    queue = deque([('0000', 0)])                                           # (state, number of turns to reach it)
    while queue:
        state, steps = queue.popleft()
        for nxt in neighbors(state):
            if nxt in dead or nxt in visited:
                continue
            if nxt == target:
                return steps + 1
            visited.add(nxt)
            queue.append((nxt, steps + 1))
    return -1


if __name__ == "__main__":
    print(open_lock(["8888"], "0009"))

