import java.util.*;

public class Main {
    int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;
        if (target.equals("0000")) return 0;

        Set<String> visited = new HashSet<>();
        visited.add("0000");
        Queue<String> queue = new ArrayDeque<>();                                       // a TRUE queue: O(1) enqueue/dequeue
        queue.offer("0000");
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();                                                       // process one full BFS LEVEL at a time
            steps++;
            for (int i = 0; i < size; i++) {
                String state = queue.poll();
                for (String next : neighbors(state)) {
                    if (dead.contains(next) || visited.contains(next)) continue;
                    if (next.equals(target)) return steps;
                    visited.add(next);
                    queue.offer(next);
                }
            }
        }
        return -1;
    }

    List<String> neighbors(String state) {
        List<String> result = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            int digit = state.charAt(i) - '0';
            for (int delta : new int[]{1, -1}) {
                int newDigit = ((digit + delta) % 10 + 10) % 10;
                result.add(state.substring(0, i) + newDigit + state.substring(i + 1));
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] deadends = {"8888"};
        System.out.println(solution.openLock(deadends, "0009"));
    }
}

